def direction(s):
    return (s[1][0]-s[0][0], s[1][1]-s[0][1])
junctions = []
for i in range(len(segs)):
    for j in range(i+1, len(segs)):
        pts_i = {segs[i][0], segs[i][1]}
        pts_j = {segs[j][0], segs[j][1]}
        shared = pts_i & pts_j
        if shared:
