PARTS = {"body": 0.5, "wheel_front": 0.25, "wheel_rear": 0.25}
TAU = 0.7
def decide(found, label):
    score = sum(PARTS[p] for p in found)
    missing = [p for p in PARTS if p not in found]
    print("%-28s score=%.2f missing=%s -> %s" % (
        label, score, missing if missing else "none",
        "CAR FOUND" if score >= TAU else "not a car"))
