def relations_ok(body, roof):
    (x0,y0),(x1,y1) = body
    apex = roof[1]
    above = apex[1] > max(y0, y1)
    centered = min(x0,x1) <= apex[0] <= max(x0,x1)
    return above and centered, {"above": above, "centered": centered}
