BUDGET = 2
def spring_cost(detected, ideal):
    return sum((d-i)**2 for d, i in zip(detected, ideal))
ideal_roof_apex = (2, 6)
for label, apex in (("roof shifted 1px", (3, 6)), ("roof shifted 3px", (5, 6))):
    cost = spring_cost(apex, ideal_roof_apex)
    print("%-16s displacement cost=%d budget=%d -> %s" % (
        label, cost, BUDGET, "ACCEPTED (wobble forgiven)" if cost <= BUDGET else "REJECTED (too far gone)"))
print("Knowing-when: spring_cost <= budget. Quadratic: gentle near ideal, ruthless far away.")
